pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // We prioritize bins that leave the smallest residual (Best Fit), 
    // but penalize creating "fragmented" space that is too small for common item sizes.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / (total_items as f64 + 1.0);

    // Base score is the post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // Only open if the existing bins are highly fragmented (high mean_residual) 
    // or if we are nearing the end of the stream and need to clear space.
    if is_new_bin {
        if fitting_bins_count == 0 {
            score = 10.0; // Forced to open
        } else {
            // Penalize opening a new bin based on how many better fits we are ignoring
            score = 50.0 + (mean_residual * 0.5) + (progress * 20.0);
        }
    } else {
        // Evaluate lookahead: if the next item fits into the current post_residual,
        // we reward this placement to keep bins tightly packed.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0;
        }

        // Penalty for "Dead Zones": 
        // If the post_residual is small but > 0, it's often unusable.
        // If post_residual is between 1 and 9, it's highly likely to be wasted.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }

        // Global state awareness:
        // If we have many open bins, prioritize finishing them (lower residual).
        // If we have few open bins, we can be more flexible.
        score += (open_bins_count as f64 * 0.2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to keep bins packed tightly.
    // We add a square penalty to discourage leaving large empty gaps.
    score += (post_residual as f64).powi(2) * 0.05;

    // 2. Lookahead Synergy: If post_residual can accommodate the next item, heavily reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 15.0;
        // Further reward if it creates a near-perfect fit for the next item.
        let fit_tightness = (post_residual - next_item_size) as f64;
        score -= (100.0 - fit_tightness) * 0.5;
    }

    // 3. Mean Residual Balancing: Avoid creating bins that are significantly worse than the current average.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 2.5;
    }

    // 4. New Bin Thresholding: Discourage opening a new bin unless the current fit is catastrophic.
    if bin_residual == bin_capacity {
        // If it's a new bin, only pick it if we have many open bins already or the current fit is very poor.
        // Penalty is high to force reuse of existing bins.
        score += 250.0;
        score -= (open_bins_count as f64) * 0.5;
    } else {
        // 5. Last Chance Logic: If this is the only bin that fits, prioritize it strongly.
        if fitting_bins_count == 1 {
            score -= 100.0;
        }
    }

    // 6. Progress Scaling: As we approach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (near-empty space) that are too small for common items
    // but reward filling bins tightly.
    let mut score = post * post;

    // Interaction term: If we are late in the stream, favor utilizing existing bins 
    // more aggressively to avoid trailing fragmented bins.
    let fill_pressure = (1.0 - progress) * (open_bins_count as f64);
    score += fill_pressure * (bin_capacity as f64 - post);

    // Lookahead logic: If the next item is large, penalize leaving a residual 
    // smaller than that item if we have other options.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post).powi(2) * 1.5;
        }
    }

    // New bin thresholding:
    // If this is a new bin (bin_residual == bin_capacity), set a high base cost.
    // The cost decreases as the stream progresses, making it easier to open new bins late
    // to "clean up" the packing.
    if bin_residual == bin_capacity {
        score = 800.0 - (progress * 400.0);
    } else {
        // If it's the last chance (only one bin fits), make it extremely attractive
        // to prevent opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 500.0;
        }
    }

    // Penalize deviation from the mean residual of open bins to encourage uniform packing.
    score += (post - mean_residual).abs() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize smaller post-residual (Best Fit principle)
    let mut score = post;

    // Non-linear penalty for leaving "dead space" that is likely too small for future items.
    // As progress increases, we become more conservative about creating small, unusable residuals.
    let dead_space_penalty = (post.powi(2) / bin_capacity as f64) * (1.0 + progress);
    score += dead_space_penalty;

    // Lookahead coupling: If a future item is large, penalize bins that cannot accommodate it
    // post_residual represents the space after placing the current item.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 1.5;
        }
    }

    // Heuristic for opening a new bin:
    // If bin_residual == bin_capacity, we are evaluating the cost of opening a fresh bin.
    if bin_residual == bin_capacity {
        // High penalty to open new bins early, but lower the penalty as we approach the end of the stream
        // to ensure we don't force poor fits just to keep bin count low.
        score = 45.0 + (progress * 15.0);
    } else {
        // If this is the only bin that can fit the item, give it a significant boost (lower score)
        // to prevent opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }

        // Penalize bins that deviate significantly from the mean_residual, 
        // encouraging a uniform distribution of fill levels across open bins.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (1-9), it is highly likely to be 
    // unusable for future items (min size 10). Heavily penalize these "sliver" residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item can fit in the post_residual, reduce the score 
    // to favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bin Pressure: If this is an existing bin, penalize based on current bin count.
    // If it's a new bin (bin_residual == bin_capacity), keep the base score to allow 
    // opening a new bin only if existing ones are poor fits.
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64) * 2.5;
    } else {
        // High penalty for opening a new bin if other bins can accommodate the item.
        score += (fitting_bins_count as f64) * 60.0;
    }

    // 4. Mean Residual Balancing: Avoid creating bins that deviate significantly from 
    // the current average residual (maintains "tightness" across all bins).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // 5. Progression weighting: As we near the end of the stream, prioritize closing 
    // gaps over opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: Heavily penalize small gaps that are unlikely to fit future items.
    // If post_residual is in the range [1, 9], it is extremely likely to become unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 85.0;
    }

    // 2. Lookahead optimization: If a future item exists, prefer bins where the post_residual 
    // can accommodate the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0;
        } else {
            score += 20.0;
        }
    }

    // 3. Open bin pressure: Penalize opening a new bin if other bins are available.
    // This discourages "new bin" selection unless the fit is perfect (Best Fit).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 50.0;
    }

    // 4. Fitting constraints: If this is the only bin that can fit the item, 
    // heavily reward it to prevent forcing a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. Mean residual balance: Avoid bins that deviate significantly from the mean 
    // to keep bin utilization uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
}
